"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Evidence-reliability confirmation: the report-only multi-factor cluster interval of the 19 key claims (registration
section 4, summarised in docs/evaluation_protocol.md, "only reported": computed after the main result from the stored
backbone outputs). Written 2026-11-24 after the replication result; nothing here changes a verdict of the result file.

Method (as the grouped package's combination, p1v4_grounding_report.boot_se / p1v4_noise_final.boot_se_factors):
  - the units are the claim's dialogue units; every question of a unit carries the unit's weight;
  - cluster factors: conversation script, event recording group, second recording group (decoy / door), background
    noise recording, user voice (p1v4_score.unit_table; the noise report's five factors, amendment 13.1);
  - Poisson(1) weights per cluster, B = 2,000, seed 1; the variance combined over all factor subsets by inclusion and
    exclusion (floored at the largest one-way variance);
  - interval = point +- t(0.975, G - 1) x SE, G = clusters of the factor with the largest one-way SE (package v0.6
    15.2); the normal interval is kept beside it;
  - the same statistics as p1v4_reliability_confirm.candidate_claims, computed with weights (AUROC: weighted
    Mann-Whitney with ties counted half); with all weights 1 they must reproduce the stored point exactly.
Verdicts use the registration's reading rule on this interval (report only).
usage: [P1V4_FINAL_RUN=1] .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_reliability_cluster.py <split>
"""
import itertools
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_noise_final as NF  # noqa: E402
import p1v4_reliability_confirm as CF  # noqa: E402
import p1v4_score as S  # noqa: E402

B, SEED, CHUNK = 2000, 1, 250
FACTORS = NF.FIVE


# ------------------------------------------------------------------------------------------------ weighted statistics

class Items:
    """Arrays of one item set, indexed by unit column."""

    def __init__(self, items, col):
        self.u = np.array([col[x[0]] for x in items], int)
        self.conf = np.array([bool(x[4]) for x in items])
        self.right = np.array([bool(x[6]) for x in items])
        self.score = np.array([np.nan if x[8] is None else float(x[8]) for x in items]) if items and len(items[0]) > 8 \
            else None


def w_acc(W, it):
    w = W[:, it.u]
    return (w * it.right).sum(1) / w.sum(1)


def w_cer(W, it):
    w = W[:, it.u] * it.conf
    return (w * ~it.right).sum(1) / w.sum(1)


def w_auroc(W, it):
    """AUROC of right vs wrong with weights; ties count half (= p1v4_reliability_confirm.auroc at weights 1)."""
    order = np.argsort(it.score, kind="mergesort")
    s, r, uu = it.score[order], it.right[order], it.u[order]
    starts = np.r_[0, np.flatnonzero(np.diff(s)) + 1]
    out = []
    for b0 in range(0, W.shape[0], CHUNK):
        w = W[b0:b0 + CHUNK][:, uu]
        wp = np.where(r, w, 0.0)
        P = np.add.reduceat(wp, starts, axis=1)
        N = np.add.reduceat(w - wp, starts, axis=1)
        below = np.cumsum(N, axis=1) - N
        out.append((P * (below + 0.5 * N)).sum(1) / (P.sum(1) * N.sum(1)))
    return np.concatenate(out)


def key_specs(Q):
    """(claim prefix, sets, statistic, kind) of the 19 key claims, as candidate_claims builds them."""
    pooled = lambda p, c, n: [x for lv in CF.LEVELS for x in Q[(p, c, n, lv, "all")]]   # noqa: E731
    sp = []
    for p in ("r_hear", "s_move"):
        for lv in ("dnoise20", "dnoise30", "dnoise40"):
            sp.append((f"M1 {p} {lv}", {"a": Q[(p, "T_off_truth", "2d", lv, "all")],
                                         "b": Q[(p, "T_off_truth", "old head", lv, "all")]}, "acc"))
        sp.append((f"M2 {p} D_off_none dnoise40", {"a": Q[(p, "D_off_none", "2d", "dnoise40", "all")]}, "cer1"))
    sp.append(("V4a r_hear dnoise40", {"a": Q[("r_hear", "D_off_none", "rel v4", "dnoise40", "all")],
                                       "b": Q[("r_hear", "D_off_none", "2d", "dnoise40", "all")]}, "cer"))
    for tag, c, a_, b_ in (("V4b", "D_off_none", "rel v4", "2d"), ("V5s", "C_off_fake", "rel v5", "2d"),
                           ("TD1", "C_off_fake", "rel v5", "rel v4"), ("TD1", "T_off_truth", "rel v5", "rel v4"),
                           ("TD2", "C_off_fake", "rel v5 label-free only", "rel v5"),
                           ("TD2", "T_off_truth", "rel v5 label-free only", "rel v5")):
        sp.append((f"{tag} r_hear {c}", {"a": pooled("r_hear", c, a_), "b": pooled("r_hear", c, b_)}, "auroc"))
    for p, c, lv in (("s_move", "A_on_none", "dnoise40"), ("s_move", "B_on_fake", "dclean"),
                     ("r_hear", "A_on_none", "dnoise40")):
        sp.append((f"V5n {p} {c} {lv}", {"a": Q[(p, c, "rel v5", lv, "covered")]}, "acc1"))
    sp.append(("V5k r_hear knock A_on_none dnoise40", {"a": Q[("r_hear", "A_on_none", "rel v5", "dnoise40",
                                                               "not covered")]}, "cer1"))
    assert sorted(s[0] for s in sp) == sorted(CF.KEY), "the key claims differ from the registration's list"
    return sp


def stat_of(kind, A, Bi):
    f = {"acc": w_acc, "acc1": w_acc, "cer": w_cer, "cer1": w_cer, "auroc": w_auroc}[kind]
    if kind.endswith("1"):
        return lambda W: f(W, A)
    return lambda W: f(W, A) - f(W, Bi)


def passes(pt, st):
    """The point on the passing side of the claim's bar (equivalence: inside +-bar)."""
    if st["higher"] == "eq":
        return abs(pt) < st["bar"]
    return pt > st["bar"] if st["higher"] else pt < st["bar"]


# ------------------------------------------------------------------------------------------------ interval

def se_factors(units, lab, stat):
    """= p1v4_noise_final.boot_se_factors (same draws), also returning the one-way SEs."""
    from scipy.stats import t as tdist
    rng = np.random.default_rng(SEED)
    names = list(lab)

    def var_by(keys):
        labels = ["|".join(str(lab[k][i]) for k in keys) for i in range(len(units))]
        lv = {x: j for j, x in enumerate(sorted(set(labels)))}
        idx = np.array([lv[x] for x in labels])
        w = rng.poisson(1.0, (B, len(lv)))[:, idx].astype(float)
        v = stat(w)
        return float(np.nanvar(v)), int(np.isnan(v).sum())
    one, nan_draws = {}, 0
    for k in names:
        one[k], nn = var_by([k])
        nan_draws += nn
    total = 0.0
    for r in range(1, len(names) + 1):
        for combo in itertools.combinations(names, r):
            if r == 1:
                total += one[combo[0]]
            else:
                v, nn = var_by(list(combo))
                nan_draws += nn
                total += (-1) ** (r + 1) * v
    se = float(np.sqrt(max(total, max(one.values()))))
    dom = max(one, key=one.get)
    g = len(set(lab[dom]))
    return se, {"dominant_factor": dom, "clusters": {k: len(set(lab[k])) for k in names},
                "one_way_se": {k: float(np.sqrt(v)) for k, v in one.items()},
                "t_crit": float(tdist.ppf(0.975, max(1, g - 1))), "undefined_draws": nan_draws}


def main(split):
    t0 = time.time()
    if split != "dev":
        CF.check_freeze()
    src = f"results/main_v04/reliability_confirm_{split}.json"
    stored = json.load(open(src))["claims"]
    out_path = f"results/main_v04/reliability_confirm_{split}_cluster.json"
    rows, rows_by, groups, wins = CF.grid(split)
    T = S.unit_table(rows, {}, S.load_groups(split))
    Q, _, wins_, _ = CF.build_items(split)
    print(f"items built ({time.time() - t0:.0f} s)", flush=True)
    res = {"split": split, "source": src, "method": __doc__.split("Method")[1].split("Verdicts")[0].strip(),
           "factors": list(FACTORS), "B": B, "seed": SEED, "claims": {}}
    for prefix, sets, kind in key_specs(Q):
        name = next(k for k in stored if k.startswith(prefix + ":"))
        st = stored[name]
        units = sorted({x[0] for items in sets.values() for x in items})
        col = {u: i for i, u in enumerate(units)}
        A = Items(sets["a"], col)
        Bi = Items(sets["b"], col) if "b" in sets else None
        stat = stat_of(kind, A, Bi)
        pt = float(stat(np.ones((1, len(units))))[0])
        assert abs(pt - st["point"]) < 1e-9, f"{name}: weighted point {pt} != stored {st['point']}"
        lab = {f: [T[u][f] for u in units] for f in FACTORS}
        se, info = se_factors(units, lab, stat)
        ci_t = [pt - info["t_crit"] * se, pt + info["t_crit"] * se]
        if st["higher"] == "eq":
            bar = st["bar"]
            v = ("confirmed" if -bar < ci_t[0] and ci_t[1] < bar else
                 "contradicted" if ci_t[0] >= bar or ci_t[1] <= -bar else
                 "unclear" if abs(pt) < bar else "not confirmed")
        else:
            v = CF.verdict(pt, ci_t, st["bar"], st["higher"], st.get("n_confident"))
        # described, not registered (as the noise report's G5 rows, amendment 13 / package 15.7): the claim within each
        # background-noise environment and with each one left out (the dnoise levels make that recording louder)
        nz = np.array([str(x) for x in lab["noise"]])
        per_env = {}
        for env in sorted(set(nz)):
            inside = (nz == env).astype(float)[None, :]
            per_env[env.replace("\\", "/").split("/")[-2] if "/" in env.replace("\\", "/") else env] = {
                "point": float(stat(inside)[0]), "n_units": int(inside.sum()),
                "left_out_point": float(stat(1.0 - inside)[0]),
                "passing_side": passes(float(stat(inside)[0]), st)}
        res["claims"][name] = {"point": pt, "se": se, "ci95_t": ci_t, "ci95_normal": [pt - 1.96 * se, pt + 1.96 * se],
                               **info, "n_units": len(units), "verdict_cluster": v,
                               "verdict_unit_bootstrap": st["verdict"], "ci95_unit_bootstrap": st["ci95"][:2],
                               "bar": st["bar"], "higher": st["higher"], "by_noise_environment": per_env}
        envs = " ".join(f"{k}:{e['point']:+.3f}{'' if e['passing_side'] else '!'}" for k, e in per_env.items())
        print(f"{v:13s} (unit {st['verdict']:13s}) {prefix:38s} {pt:+.3f} t[{ci_t[0]:+.3f}, {ci_t[1]:+.3f}] "
              f"unit[{st['ci95'][0]:+.3f}, {st['ci95'][1]:+.3f}] dom {info['dominant_factor']} "
              f"G {info['clusters'][info['dominant_factor']]} | {envs}", flush=True)
    from collections import Counter
    res["summary"] = dict(Counter(c["verdict_cluster"] for c in res["claims"].values()))
    res["seconds"] = round(time.time() - t0)
    json.dump(res, open(out_path, "w"), indent=1)
    print("cluster verdicts:", res["summary"], f"-> {out_path} ({res['seconds']} s)", flush=True)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit(__doc__)
    main(sys.argv[1])
